const body = $input.item.json.body ?? $input.item.json;

// Ignore messages sent by the bot itself
if (body.payload?.fromMe === true) {
  return [{ json: { skip: true } }];
}

// Extract fields
const event       = body.event ?? 'message';
const sessionName = body.session ?? '';
const payload     = body.payload ?? {};

const fromRaw     = payload.from ?? '';
const chatId      = payload.from ?? '';
const phoneNumber = fromRaw.replace('@c.us', '').replace('@g.us', '');
const messageText = payload.body ?? payload.text ?? '';
const timestamp   = payload.timestamp ? new Date(payload.timestamp * 1000).toISOString() : new Date().toISOString();
const messageId   = payload.id ? String(payload.id) : `fallback_${timestamp}`;

if (!messageText.trim()) {
  return [{ json: { skip: true, reason: 'no_text' } }];
}

return [{
  json: {
    skip: false,
    sessionName,
    phoneNumber,
    chatId,
    messageText,
    messageId,
    timestamp,
    event
  }
}];

// Build the context string from last 5 messages for the AI classifier
const contextMessages = $input.all();
const businessData    = $('Get Business by Session').item.json;
const normalized      = $('Normalize Payload').item.json;

const historyLines = contextMessages
  .slice(0, 3)   // take last 3 turns
  .map(m => `[${m.json.direction.toUpperCase()}]: ${m.json.message_text}`)
  .join('\n');

return [{
  json: {
    business_id:   businessData.business_id,
    business_name: businessData.business_name,
    phoneNumber:   normalized.phoneNumber,
    chatId:        normalized.chatId,
    messageText:   normalized.messageText,
    contextHistory: historyLines || '(no prior conversation)',
    prompt: `Business: ${businessData.business_name}\n\nConversation history (most recent first):\n${historyLines || '(no prior conversation)'}\n\nCustomer message: ${normalized.messageText}`
  }
}];

// Robust Classification Parser
const rawResponse = $input.item.json.output ?? $input.item.json.text ?? $input.item.json;
const ctx = $('Build AI Context').item.json;
const msgText = (ctx.messageText || '').trim().toLowerCase();

let classification = null;

const greetings = ['hi', 'hello', 'hey', 'good morning', 'good evening', 'hii', 'hiii', 'yo', 'sup', 'whatsup', 'hi there', 'hello there'];
if (greetings.includes(msgText)) {
  classification = {
    intent: 'GENERAL_QUESTION',
    confidence: 1.0,
    entities: {},
    language: 'en'
  };
} else {
  try {
    let str = typeof rawResponse === 'string' ? rawResponse : JSON.stringify(rawResponse);
    str = str.replace(/```json\n?/g, '').replace(/```\n?/g, '').strip ? str.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim() : str.trim();

    // First parse pass
    let parsed = null;
    const match = str.match(/\{[\s\S]*\}/);
    if (match) {
      parsed = JSON.parse(match[0]);
    } else {
      parsed = JSON.parse(str);
    }

    // Handle ReAct action_input wrapper if present!
    if (parsed && typeof parsed === 'object' && parsed.action_input) {
      let aiInput = parsed.action_input;
      if (typeof aiInput === 'string') {
        const innerMatch = aiInput.match(/\{[\s\S]*\}/);
        parsed = JSON.parse(innerMatch ? innerMatch[0] : aiInput);
      } else if (typeof aiInput === 'object') {
        parsed = aiInput;
      }
    }

    classification = parsed;
  } catch (e) {
    classification = {
      intent: 'GENERAL_QUESTION',
      confidence: 0.5,
      entities: {},
      language: 'en'
    };
  }
}

return [{
  json: {
    ...ctx,
    intent:     (classification && classification.intent)     || 'GENERAL_QUESTION',
    confidence: (classification && classification.confidence) ?? 1.0,
    entities:   (classification && classification.entities)   || {},
    language:   (classification && classification.language)   || 'en'
  }
}];

parameters.query:
UPDATE conversations
SET detected_intent = '{{ $json.intent }}', confidence = {{ $json.confidence || 0 }}
WHERE business_id = '{{ $("Get Business by Session").first().json.business_id }}' AND customer_number = '{{ $("Normalize Payload").first().json.phoneNumber }}'
  AND created_at = (SELECT MAX(created_at) FROM conversations WHERE business_id = '{{ $("Get Business by Session").first().json.business_id }}' AND customer_number = '{{ $("Normalize Payload").first().json.phoneNumber }}');
